package pyfmt

import (
	"encoding/json"
	"math"
	"os"
	"testing"
)

// TestMatchesPython checks every helper against the strings Python produced (testdata/py_fmt.json,
// generated by bounce_gen/gen_fmt.py).
func TestMatchesPython(t *testing.T) {
	raw, err := os.ReadFile("testdata/py_fmt.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct {
		Rows []struct {
			X   float64 `json:"x"`
			G   string  `json:"g"`
			F4  string  `json:"f4"`
			FS4 string  `json:"fs4"`
			FS2 string  `json:"fs2"`
			F0  string  `json:"f0"`
			P2  string  `json:"p2"`
			P1  string  `json:"p1"`
			P0  string  `json:"p0"`
			R5  float64 `json:"r5"`
			R2  float64 `json:"r2"`
			R12 float64 `json:"r12"`
			R   float64 `json:"r"`
			FC0 string  `json:"fc0"`
			FC2 string  `json:"fc2"`
		} `json:"rows"`
		Ints []struct {
			N int64  `json:"n"`
			C string `json:"c"`
		} `json:"ints"`
	}
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatal(err)
	}
	for _, r := range fx.Rows {
		x := r.X
		eq := func(name, got, want string) {
			t.Helper()
			if got != want {
				t.Errorf("%s(%v) = %q, python %q", name, x, got, want)
			}
		}
		eq("G", G(x), r.G)
		eq("F4", F(x, 4), r.F4)
		eq("FS4", FS(x, 4), r.FS4)
		eq("FS2", FS(x, 2), r.FS2)
		eq("F0", F(x, 0), r.F0)
		eq("Pct2", Pct(x, 2), r.P2)
		eq("Pct1", Pct(x, 1), r.P1)
		eq("Pct0", Pct(x, 0), r.P0)
		eq("FComma0", FComma(x, 0), r.FC0)
		eq("FComma2", FComma(x, 2), r.FC2)
		for _, c := range []struct {
			n    int
			want float64
		}{{5, r.R5}, {2, r.R2}, {12, r.R12}} {
			if got := Round(x, c.n); got != c.want && !(got == 0 && c.want == 0) {
				t.Errorf("Round(%v, %d) = %v, python %v", x, c.n, got, c.want)
			}
		}
		if got := float64(Int(x)); got != r.R {
			t.Errorf("Int(%v) = %v, python %v", x, got, r.R)
		}
	}
	for _, r := range fx.Ints {
		if got := Comma(r.N); got != r.C {
			t.Errorf("Comma(%d) = %q, python %q", r.N, got, r.C)
		}
	}
	if len(fx.Rows) < 300 {
		t.Fatalf("only %d rows", len(fx.Rows))
	}
}

func TestMisc(t *testing.T) {
	if G(math.NaN()) != "nan" || G(math.Inf(1)) != "inf" || ReprStrs([]string{"a", "b"}) != "['a', 'b']" {
		t.Fatal("specials")
	}
}
